import { Pool, type PoolClient } from 'pg';
import { afterAll, beforeAll, describe, expect, test } from 'vitest';

import { executeQuery } from '../../src/database';
import { createSubmitterAccessRepository } from '../../src/modules/submitter-access/submitter-access.repository';
import { assertSafeTestDatabase } from '../../scripts/test-database-safety';

const sourcePrefix = `submitter-access-test-${process.pid}`;

describe.sequential('submitter access request database integration', () => {
  let pool: Pool | undefined;

  function databasePool(): Pool {
    if (!pool) {
      throw new Error('Test database pool has not been initialised.');
    }

    return pool;
  }

  async function withRolledBackTransaction(
    operation: (client: PoolClient) => Promise<void>,
  ): Promise<void> {
    const client = await databasePool().connect();

    try {
      await client.query('BEGIN');
      await operation(client);
    } finally {
      await client.query('ROLLBACK');
      client.release();
    }
  }

  async function insertAccount(
    client: PoolClient,
    suffix: string,
    approvalState: 'not_requested' | 'pending' | 'approved' | 'rejected',
  ): Promise<string> {
    const result = await executeQuery<{ accountId: string }>(
      client,
      `
        INSERT INTO app_user (
          auth_provider,
          auth_subject,
          submitter_approval_state
        )
        VALUES ('test', $1, $2)
        RETURNING app_user_id::text AS "accountId"
      `,
      [`${sourcePrefix}-${suffix}`, approvalState],
    );

    return result.rows[0].accountId;
  }

  beforeAll(() => {
    const databaseUrl = assertSafeTestDatabase(
      process.env.DATABASE_URL_TEST,
      process.env.DATABASE_URL,
      process.env.NODE_ENV,
    );

    pool = new Pool({
      connectionString: databaseUrl.toString(),
    });
  });

  afterAll(async () => {
    if (pool) {
      await pool.end();
    }
  });

  test('persists a pending request and prevents a second active request', async () => {
    await withRolledBackTransaction(async (client) => {
      const accountId = await insertAccount(client, 'new-request', 'not_requested');
      const repository = createSubmitterAccessRepository(client);

      await expect(repository.requestAccess(accountId)).resolves.toEqual({
        accountId,
        approvalState: 'pending',
      });

      const persisted = await executeQuery<{ approvalState: string }>(
        client,
        `
          SELECT submitter_approval_state AS "approvalState"
          FROM app_user
          WHERE app_user_id = $1
        `,
        [accountId],
      );

      expect(persisted.rows[0].approvalState).toBe('pending');

      await expect(repository.requestAccess(accountId)).rejects.toMatchObject({
        code: 'REQUEST_ALREADY_PENDING',
      });
    });
  });

  test('allows a previously rejected account to request access again', async () => {
    await withRolledBackTransaction(async (client) => {
      const accountId = await insertAccount(client, 'rejected-request', 'rejected');
      const repository = createSubmitterAccessRepository(client);

      await expect(repository.requestAccess(accountId)).resolves.toEqual({
        accountId,
        approvalState: 'pending',
      });

      const persisted = await executeQuery<{ approvalState: string }>(
        client,
        `
          SELECT submitter_approval_state AS "approvalState"
          FROM app_user
          WHERE app_user_id = $1
        `,
        [accountId],
      );

      expect(persisted.rows[0].approvalState).toBe('pending');
    });
  });

  test('does not change an already-approved submitter', async () => {
    await withRolledBackTransaction(async (client) => {
      const accountId = await insertAccount(client, 'approved-request', 'approved');
      const repository = createSubmitterAccessRepository(client);

      await expect(repository.requestAccess(accountId)).rejects.toMatchObject({
        code: 'SUBMITTER_ALREADY_APPROVED',
      });

      const persisted = await executeQuery<{ approvalState: string }>(
        client,
        `
          SELECT submitter_approval_state AS "approvalState"
          FROM app_user
          WHERE app_user_id = $1
        `,
        [accountId],
      );

      expect(persisted.rows[0].approvalState).toBe('approved');
    });
  });
});

import {
  administratorSubmitterAccessResponseSchema,
  administratorSubmitterAccessUpdateSchema,
  administratorUserManagementResponseSchema,
} from '@sport-analytics/contracts';
import type { RequestHandler, Response } from 'express';

import type { ApplicationAccount } from '../accounts/account';
import {
  AdminManagementConflictError,
  AdminUserNotFoundError,
  InvalidCompetitionScopesError,
} from './admin.errors';
import type { AdminService } from './admin.service';

function getAuthenticatedAccount(response: Response): ApplicationAccount {
  const account = response.locals.authenticatedAccount as ApplicationAccount | undefined;

  if (!account) {
    throw new Error('Administrator controller requires an authenticated application account');
  }

  return account;
}

function validationDetails(
  issues: { message: string; path: PropertyKey[] }[],
): { code: string; message: string; field?: string }[] {
  return issues.map((issue) => ({
    code: 'INVALID_FIELD',
    message: issue.message,
    ...(issue.path.length > 0 ? { field: issue.path.join('.') } : {}),
  }));
}

function isDatabaseIdentifier(value: string): boolean {
  if (!/^\d+$/.test(value)) {
    return false;
  }

  try {
    return BigInt(value) <= 9_223_372_036_854_775_807n;
  } catch {
    return false;
  }
}

export function createAdminListUsersController(service: AdminService): RequestHandler {
  return (_request, response, next) => {
    void service
      .listUsers()
      .then((result) => {
        response.status(200).json(administratorUserManagementResponseSchema.parse(result));
      })
      .catch(next);
  };
}

export function createAdminUpdateSubmitterAccessController(service: AdminService): RequestHandler {
  return (request, response, next) => {
    const targetAccountId = request.params.userId;

    if (!targetAccountId || !isDatabaseIdentifier(targetAccountId)) {
      response.status(422).json({
        error: {
          code: 'VALIDATION_FAILED',
          message: 'The submitter access update is invalid.',
          details: [
            {
              code: 'INVALID_FIELD',
              field: 'userId',
              message: 'The user identifier is invalid.',
            },
          ],
        },
      });
      return;
    }

    const parsed = administratorSubmitterAccessUpdateSchema.safeParse(request.body);

    if (!parsed.success) {
      response.status(422).json({
        error: {
          code: 'VALIDATION_FAILED',
          message: 'The submitter access update is invalid.',
          details: validationDetails(parsed.error.issues),
        },
      });
      return;
    }

    const malformedCompetitionIds = parsed.data.competitionIds.filter(
      (competitionId) => !isDatabaseIdentifier(competitionId),
    );

    if (malformedCompetitionIds.length > 0) {
      response.status(422).json({
        error: {
          code: 'VALIDATION_FAILED',
          message: 'The submitter access update is invalid.',
          details: [
            {
              code: 'INVALID_FIELD',
              field: 'competitionIds',
              message: 'Every competition identifier must be valid.',
            },
          ],
        },
      });
      return;
    }

    let administrator: ApplicationAccount;

    try {
      administrator = getAuthenticatedAccount(response);
    } catch (error) {
      next(error);
      return;
    }

    void service
      .updateSubmitterAccess(administrator, targetAccountId, parsed.data)
      .then((result) => {
        response.status(200).json(administratorSubmitterAccessResponseSchema.parse(result));
      })
      .catch((error: unknown) => {
        if (error instanceof AdminUserNotFoundError) {
          response.status(404).json({
            error: {
              code: 'USER_NOT_FOUND',
              message: error.message,
            },
          });
          return;
        }

        if (error instanceof InvalidCompetitionScopesError) {
          response.status(422).json({
            error: {
              code: 'INVALID_COMPETITION_SCOPE',
              message: error.message,
              details: [
                {
                  code: 'INVALID_SCOPE',
                  field: 'competitionIds',
                  message: 'Select only competition scopes that currently exist.',
                },
              ],
            },
          });
          return;
        }

        if (error instanceof AdminManagementConflictError) {
          response.status(409).json({
            error: {
              code: error.code,
              message: error.message,
            },
          });
          return;
        }

        next(error);
      });
  };
}

export function createAdminRejectSubmitterAccessRequestController(
  service: AdminService,
): RequestHandler {
  return (request, response, next) => {
    const targetAccountId = request.params.userId;

    if (!targetAccountId || !isDatabaseIdentifier(targetAccountId)) {
      response.status(422).json({
        error: {
          code: 'VALIDATION_FAILED',
          message: 'The submitter access rejection is invalid.',
          details: [
            {
              code: 'INVALID_FIELD',
              field: 'userId',
              message: 'The user identifier is invalid.',
            },
          ],
        },
      });
      return;
    }

    let administrator: ApplicationAccount;

    try {
      administrator = getAuthenticatedAccount(response);
    } catch (error) {
      next(error);
      return;
    }

    void service
      .rejectSubmitterAccessRequest(administrator, targetAccountId)
      .then((result) => {
        response.status(200).json(administratorSubmitterAccessResponseSchema.parse(result));
      })
      .catch((error: unknown) => {
        if (error instanceof AdminUserNotFoundError) {
          response.status(404).json({
            error: {
              code: 'USER_NOT_FOUND',
              message: error.message,
            },
          });
          return;
        }

        if (error instanceof AdminManagementConflictError) {
          response.status(409).json({
            error: {
              code: error.code,
              message: error.message,
            },
          });
          return;
        }

        next(error);
      });
  };
}

