import {
  submitterAccessRequestResponseSchema,
  submitterAccessRequestSchema,
} from '@sport-analytics/contracts';
import type { RequestHandler, Response } from 'express';

import type { ApplicationAccount } from '../accounts/account';
import {
  InvalidRequestedCompetitionError,
  SubmitterAccessConflictError,
} from './submitter-access.errors';
import type { SubmitterAccessService } from './submitter-access.service';

function getAuthenticatedAccount(response: Response): ApplicationAccount {
  const account = response.locals.authenticatedAccount as ApplicationAccount | undefined;

  if (!account) {
    throw new Error('Submitter access controller requires an authenticated application account');
  }

  return account;
}

export function createSubmitterAccessController(service: SubmitterAccessService): RequestHandler {
  return (request, response, next) => {
    const parsed = submitterAccessRequestSchema.safeParse(request.body);

    if (!parsed.success || !isDatabaseIdentifier(parsed.data.competitionId)) {
      response.status(422).json({
        error: {
          code: 'VALIDATION_FAILED',
          message: 'The submitter access request is invalid.',
          details: [
            {
              code: 'INVALID_FIELD',
              field: 'competitionId',
              message: 'Select a valid competition.',
            },
          ],
        },
      });
      return;
    }

    let account: ApplicationAccount;

    try {
      account = getAuthenticatedAccount(response);
    } catch (error) {
      next(error);
      return;
    }

    void service
      .requestAccess(account, parsed.data)
      .then((result) => {
        response.status(201).json(submitterAccessRequestResponseSchema.parse(result));
      })
      .catch((error: unknown) => {
        if (error instanceof SubmitterAccessConflictError) {
          response.status(409).json({
            error: {
              code: error.code,
              message: error.message,
            },
          });
          return;
        }

        if (error instanceof InvalidRequestedCompetitionError) {
          response.status(422).json({
            error: {
              code: 'INVALID_COMPETITION_SCOPE',
              message: error.message,
              details: [
                {
                  code: 'INVALID_SCOPE',
                  field: 'competitionId',
                  message: 'Select a competition that currently exists.',
                },
              ],
            },
          });
          return;
        }

        next(error);
      });
  };
}

function isDatabaseIdentifier(value: string): boolean {
  if (!/^[1-9]\d*$/.test(value)) {
    return false;
  }

  try {
    return BigInt(value) <= 9_223_372_036_854_775_807n;
  } catch {
    return false;
  }
}
import type {
  SubmitterAccessRequest,
  SubmitterAccessRequestResponse,
} from '@sport-analytics/contracts';
import type { ApplicationAccount } from '../accounts/account';
import { SubmitterAccessConflictError } from './submitter-access.errors';
import {
  createSubmitterAccessRepository,
  type SubmitterAccessRepository,
} from './submitter-access.repository';

export interface SubmitterAccessService {
  requestAccess(
    account: ApplicationAccount,
    request: SubmitterAccessRequest,
  ): Promise<SubmitterAccessRequestResponse>;
}

export function createSubmitterAccessService(
  repository?: SubmitterAccessRepository,
): SubmitterAccessService {
  let resolvedRepository = repository;

  return {
    async requestAccess(account, request) {
      if (account.role === 'submitter' || account.role === 'admin') {
        throw new SubmitterAccessConflictError(
          'SUBMITTER_ALREADY_APPROVED',
          'The authenticated account already has submission access.',
        );
      }

      resolvedRepository ??= createSubmitterAccessRepository();
      const persistedRequest = await resolvedRepository.requestAccess(
        account.accountId,
        request.competitionId,
      );

      return {
        data: persistedRequest,
      };
    },
  };
}
import { z } from 'zod';

import { apiDateTimeSchema, apiIdentifierSchema } from './api';

export const APPLICATION_ROLES = ['viewer', 'submitter', 'admin'] as const;

export const applicationRoleSchema = z.enum(APPLICATION_ROLES);

/** @deprecated Request-workflow state only. Use applicationRoleSchema for authorization. */
export const submitterApprovalStateSchema = z.enum([
  'not_requested',
  'pending',
  'approved',
  'rejected',
]);

export const competitionScopeSchema = z
  .object({
    competitionId: apiIdentifierSchema,
    name: z.string().min(1),
  })
  .strict();

export const currentUserProfileSchema = z
  .object({
    id: apiIdentifierSchema,
    subject: z.string().min(1),
    displayName: z.string().min(1).nullable(),
    role: applicationRoleSchema,
    approvalState: submitterApprovalStateSchema,
    requestedCompetition: competitionScopeSchema.nullable(),
    competitionIds: z
      .array(apiIdentifierSchema)
      .refine((competitionIds) => new Set(competitionIds).size === competitionIds.length, {
        message: 'Competition identifiers must be unique.',
      }),
  })
  .strict();

export const currentUserProfileResponseSchema = z
  .object({
    user: currentUserProfileSchema,
  })
  .strict();

export const accountDeletionRequestSchema = z
  .object({
    confirmation: z.literal('DELETE'),
  })
  .strict();

export const accountDeletionResponseSchema = z
  .object({
    data: z
      .object({
        status: z.literal('deleted'),
        retainedCricketData: z.literal(true),
      })
      .strict(),
  })
  .strict();

export const submitterAccessRequestSchema = z
  .object({
    competitionId: apiIdentifierSchema,
  })
  .strict();

export const submitterAccessRequestResponseSchema = z
  .object({
    data: z
      .object({
        accountId: apiIdentifierSchema,
        approvalState: z.literal('pending'),
        requestedCompetition: competitionScopeSchema,
      })
      .strict(),
  })
  .strict();

export const administratorCompetitionScopeSchema = competitionScopeSchema;

export const administratorAuditActorSchema = z
  .object({
    id: apiIdentifierSchema,
    displayName: z.string().min(1).nullable(),
  })
  .strict();

export const administratorManagedUserSchema = z
  .object({
    id: apiIdentifierSchema,
    displayName: z.string().min(1).nullable(),
    role: applicationRoleSchema,
    approvalState: submitterApprovalStateSchema,
    requestedCompetition: competitionScopeSchema.nullable(),
    competitionScopes: z
      .array(administratorCompetitionScopeSchema)
      .refine(
        (scopes) => new Set(scopes.map((scope) => scope.competitionId)).size === scopes.length,
        { message: 'Competition scopes must be unique.' },
      ),
    disabled: z.boolean(),
    updatedAt: apiDateTimeSchema,
    submitterAccessUpdatedAt: apiDateTimeSchema.nullable(),
    submitterAccessUpdatedBy: administratorAuditActorSchema.nullable(),
  })
  .strict();

export const administratorUserManagementResponseSchema = z
  .object({
    data: z
      .object({
        users: z.array(administratorManagedUserSchema),
        availableScopes: z
          .array(administratorCompetitionScopeSchema)
          .refine(
            (scopes) => new Set(scopes.map((scope) => scope.competitionId)).size === scopes.length,
            { message: 'Available competition scopes must be unique.' },
          ),
      })
      .strict(),
  })
  .strict();

export const administratorSubmitterAccessUpdateSchema = z
  .object({
    approved: z.boolean(),
    competitionIds: z
      .array(apiIdentifierSchema)
      .refine((competitionIds) => new Set(competitionIds).size === competitionIds.length, {
        message: 'Competition identifiers must be unique.',
      }),
  })
  .strict()
  .superRefine((value, context) => {
    if (value.approved && value.competitionIds.length === 0) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['competitionIds'],
        message: 'Select at least one competition scope before approving a submitter.',
      });
    }

    if (!value.approved && value.competitionIds.length > 0) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['competitionIds'],
        message: 'Revoked submitters cannot retain competition scopes.',
      });
    }
  });

export const administratorSubmitterAccessResponseSchema = z
  .object({
    data: administratorManagedUserSchema,
  })
  .strict();

export type ApplicationRole = z.infer<typeof applicationRoleSchema>;
/** @deprecated Request-workflow state only. Use ApplicationRole for authorization. */
export type SubmitterApprovalState = z.infer<typeof submitterApprovalStateSchema>;
export type CurrentUserProfile = z.infer<typeof currentUserProfileSchema>;
export type CurrentUserProfileResponse = z.infer<typeof currentUserProfileResponseSchema>;
export type AccountDeletionRequest = z.infer<typeof accountDeletionRequestSchema>;
export type AccountDeletionResponse = z.infer<typeof accountDeletionResponseSchema>;
export type CompetitionScope = z.infer<typeof competitionScopeSchema>;
export type SubmitterAccessRequest = z.infer<typeof submitterAccessRequestSchema>;
export type SubmitterAccessRequestResponse = z.infer<typeof submitterAccessRequestResponseSchema>;
export type AdministratorCompetitionScope = z.infer<typeof administratorCompetitionScopeSchema>;
export type AdministratorManagedUser = z.infer<typeof administratorManagedUserSchema>;
export type AdministratorUserManagementResponse = z.infer<
  typeof administratorUserManagementResponseSchema
>;
export type AdministratorSubmitterAccessUpdate = z.infer<
  typeof administratorSubmitterAccessUpdateSchema
>;
export type AdministratorSubmitterAccessResponse = z.infer<
  typeof administratorSubmitterAccessResponseSchema
>;
import {
  submitterAccessRequestResponseSchema,
  type Competition,
  type SubmitterAccessRequestResponse,
} from '@sport-analytics/contracts';
import type { AuthenticatedApiClient } from '../../api/client';
import { publicReadApi } from '../../api/public-read';

export class SubmitterAccessContractError extends Error {
  constructor() {
    super('The API returned an unexpected submitter access response. Please try again.');
    this.name = 'SubmitterAccessContractError';
  }
}

export class SubmitterAccessCompetitionOptionsError extends Error {
  constructor() {
    super('Available competitions could not be loaded. Please try again.');
    this.name = 'SubmitterAccessCompetitionOptionsError';
  }
}

export async function listRequestableCompetitions(signal?: AbortSignal): Promise<Competition[]> {
  const competitions: Competition[] = [];
  let cursor: string | null = null;

  try {
    do {
      const parameters = new URLSearchParams({ limit: '100' });
      if (cursor) {
        parameters.set('cursor', cursor);
      }

      const response = await publicReadApi.listCompetitions(`?${parameters.toString()}`, signal);
      competitions.push(...response.data);
      cursor = response.pagination.nextCursor;
    } while (cursor);
  } catch {
    throw new SubmitterAccessCompetitionOptionsError();
  }

  return competitions.sort(
    (left, right) =>
      left.name.localeCompare(right.name) || left.competitionId.localeCompare(right.competitionId),
  );
}

export async function requestSubmitterAccess(
  client: AuthenticatedApiClient,
  competitionId: string,
): Promise<SubmitterAccessRequestResponse> {
  const response = await client.request<unknown>('/submitter-access-requests', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ competitionId }),
  });
  const parsed = submitterAccessRequestResponseSchema.safeParse(response);

  if (!parsed.success) {
    throw new SubmitterAccessContractError();
  }

  return parsed.data;
}

